// Builds web/src/shared/ui/icons/phosphor.ts from the pinned
// @phosphor-icons/react devDependency: the path data of every icon the app
// imports from '@/shared/ui/icons', in the regular, bold and fill weights only.
// The package ships all six weights in every icon, and the three never drawn
// were most of what the icons cost in the main chunk. Run it after importing a
// new icon or bumping @phosphor-icons/react:
//
//   npm run icons
//
// tests/scripts/buildIcons.test.ts fails while the generated file is stale.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath, pathToFileURL } from 'node:url';
import type { ReactElement } from 'react';

const require = createRequire(import.meta.url);
const webRoot = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const packageRoot = path.dirname(require.resolve('@phosphor-icons/react/package.json'));
const packageVersion: string = require('@phosphor-icons/react/package.json').version;

export const ICON_MODULE = path.join(webRoot, 'src', 'shared', 'ui', 'icons', 'phosphor.ts');
export const WEIGHTS = ['regular', 'bold', 'fill'] as const;

const IMPORT = /import\s+(?:type\s+)?\{([^}]*)\}\s+from\s+'@\/shared\/ui\/icons'/g;
const ICON_NAME = /^[A-Z]\w*Icon$/;

function sourceFiles(dir: string): string[] {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const file = path.join(dir, entry.name);
    if (entry.isDirectory()) return sourceFiles(file);
    return /\.tsx?$/.test(entry.name) ? [file] : [];
  });
}

/** Every icon component imported from '@/shared/ui/icons' under src/ and tests/. */
export function importedIconNames(roots = [path.join(webRoot, 'src'), path.join(webRoot, 'tests')]): string[] {
  const names = new Set<string>();
  for (const file of roots.flatMap(sourceFiles)) {
    for (const match of fs.readFileSync(file, 'utf8').matchAll(IMPORT)) {
      for (const specifier of match[1]!.split(',')) {
        const name = specifier.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0]!;
        if (ICON_NAME.test(name)) names.add(name);
      }
    }
  }
  return [...names].sort();
}

type Weights = Map<string, ReactElement<{ children?: unknown }>>;

function pathData(icon: string, weight: string, element: ReactElement<{ children?: unknown }> | undefined): string[] {
  if (!element) throw new Error(`${icon} has no ${weight} weight`);
  const children = [element.props.children].flat() as ReactElement<Record<string, unknown>>[];
  return children.map((child) => {
    const { d, ...others } = child.props;
    if (child.type !== 'path' || typeof d !== 'string' || Object.keys(others).length > 0) {
      throw new Error(`${icon} (${weight}) draws something other than a plain <path d>; teach createIcon to draw it`);
    }
    return d;
  });
}

/** The source of phosphor.ts for these icons. */
export async function renderIconModule(names: string[]): Promise<string> {
  const lines = [
    `// Generated by web/scripts/buildIcons.ts from @phosphor-icons/react ${packageVersion}.`,
    '// Do not edit: import the icon from \'@/shared/ui/icons\' and run `npm run icons`.',
    "import { createIcon } from './createIcon';",
    '',
  ];
  for (const name of names) {
    const file = path.join(packageRoot, 'dist', 'defs', `${name.replace(/Icon$/, '')}.es.js`);
    if (!fs.existsSync(file)) throw new Error(`@phosphor-icons/react has no ${name}`);
    const weights: Weights = (await import(pathToFileURL(file).href)).default;
    const paths = WEIGHTS.map((weight) => JSON.stringify(pathData(name, weight, weights.get(weight))).replaceAll('"', "'"));
    lines.push(`export const ${name} = /* @__PURE__ */ createIcon('${name}', ${paths.join(', ')});`);
  }
  return `${lines.join('\n')}\n`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const names = importedIconNames();
  fs.writeFileSync(ICON_MODULE, await renderIconModule(names));
  console.log(`Wrote ${names.length} icons to ${path.relative(process.cwd(), ICON_MODULE)}`);
}
